from pathlib import Path

root=Path('.')
dashboard=root/'app/dashboard.tsx'
customers_route=root/'app/api/customers/route.ts'

for path in (dashboard,customers_route):
    if not path.is_file():
        raise SystemExit(f'FIRE_CUSTOMER_EDIT_FLOW=FAIL: missing {path}')

route=customers_route.read_text()
if 'export async function PATCH(request: Request)' not in route:
    route += '''\n\nexport async function PATCH(request: Request) {\n  if (!await authorized()) return Response.json({ error: "Unauthorized" }, { status: 401 });\n  try {\n    const body = await request.json() as Record<string, unknown>;\n    const id = String(body.id ?? "").trim();\n    const name = String(body.name ?? "").trim();\n    const email = String(body.email ?? "").trim();\n    const phone = String(body.phone ?? "").trim();\n    const address = String(body.address ?? "").trim();\n    const leadSource = String(body.leadSource ?? "Unknown").trim() || "Unknown";\n    if (!id) return Response.json({ error: "Customer id is required." }, { status: 400 });\n    if (!name) return Response.json({ error: "Customer name is required." }, { status: 400 });\n\n    if (id.length > 128 || name.length > 200 || email.length > 254 || phone.length > 64 || address.length > 500 || leadSource.length > 100) return Response.json({ error: "Customer details exceed allowed length." }, { status: 400 });\n    if (email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) return Response.json({ error: "Enter a valid customer email." }, { status: 400 });\n\n    const existing = await env.DB.prepare("SELECT id,created_at AS createdAt FROM customers WHERE id=? LIMIT 1").bind(id).first<{id:string;createdAt:string}>();\n    if (!existing) return Response.json({ error: "Customer not found." }, { status: 404 });\n\n    await env.DB.prepare("UPDATE customers SET name=?,email=?,phone=?,address=?,lead_source=? WHERE id=?")\n      .bind(name, email || null, phone || null, address || null, leadSource, id).run();\n\n    return Response.json({ customer: { id, name, email, phone, address, leadSource, createdAt: existing.createdAt } });\n  } catch {\n    return Response.json({ error: "We couldn't update this customer. Please try again." }, { status: 500 });\n  }\n}\n'''
    customers_route.write_text(route)

text=dashboard.read_text()
if 'function EditCustomer(' not in text:
    marker='function AddCustomer({ onAdded }: { onAdded: (customer: CustomerRow) => void }) {'
    if marker not in text:
        raise SystemExit('FIRE_CUSTOMER_EDIT_FLOW=FAIL: AddCustomer insertion marker missing')
    component='''function EditCustomer({ customer, onUpdated }: { customer: CustomerRow; onUpdated: (customer: CustomerRow) => void }) {\n  const [open,setOpen]=useState(false);\n  const [name,setName]=useState(customer.name);\n  const [email,setEmail]=useState(customer.email||"");\n  const [phone,setPhone]=useState(customer.phone||"");\n  const [address,setAddress]=useState(customer.address||"");\n  const [leadSource,setLeadSource]=useState(customer.leadSource||"Unknown");\n  const [saving,setSaving]=useState(false);\n  const [error,setError]=useState("");\n  useEffect(()=>{if(open){setName(customer.name);setEmail(customer.email||"");setPhone(customer.phone||"");setAddress(customer.address||"");setLeadSource(customer.leadSource||"Unknown");setError("");}},[open,customer]);\n  const save=async()=>{\n    if(!name.trim()){setError("Customer name is required.");return;}\n    setSaving(true);setError("");\n    try{\n      const response=await fetch("/api/customers",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:customer.id,name:name.trim(),email:email.trim(),phone:phone.trim(),address:address.trim(),leadSource})});\n      const result=await response.json() as {customer?:Partial<CustomerRow>&{id:string};error?:string};\n      if(!response.ok||!result.customer)throw new Error(result.error||"The customer could not be updated.");\n      onUpdated({...customer,...result.customer,name:name.trim(),email:email.trim(),phone:phone.trim(),address:address.trim(),leadSource});\n      setOpen(false);\n    }catch(saveError){setError(saveError instanceof Error?saveError.message:"The customer could not be updated.");}\n    finally{setSaving(false);}\n  };\n  return <Dialog open={open} onOpenChange={setOpen}>\n    <DialogTrigger asChild><Button variant="outline"><PenLine className="h-4 w-4"/> Edit customer</Button></DialogTrigger>\n    <DialogContent className="sm:max-w-[520px]">\n      <DialogHeader><DialogTitle>Edit customer</DialogTitle></DialogHeader>\n      <div className="customer-form">\n        <div><Label>Customer name</Label><Input placeholder="Full name" value={name} onChange={(event)=>setName(event.target.value)}/></div>\n        <div><Label>Email</Label><Input type="email" placeholder="customer@email.com" value={email} onChange={(event)=>setEmail(event.target.value)}/></div>\n        <div><Label>Phone</Label><Input inputMode="tel" placeholder="(918) 555-0123" value={phone} onChange={(event)=>setPhone(event.target.value)}/></div>\n        <div><Label>Service address</Label><Input placeholder="Tulsa-area address" value={address} onChange={(event)=>setAddress(event.target.value)}/></div>\n        <div><Label>How they found FIRE</Label><Select value={leadSource} onValueChange={setLeadSource}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["Unknown","Referral","Google","Facebook","Website","Repeat customer","Door knocking","Other"].map((source)=><SelectItem key={source} value={source}>{source}</SelectItem>)}</SelectContent></Select></div>\n        <p className="service-description-help">This updates the customer profile only. Existing estimates, invoices, payments, and signed agreements keep their recorded history.</p>\n        {error&&<p className="save-error" role="alert">{error}</p>}\n        <Button className="brand-button" onClick={()=>void save()} disabled={saving}>{saving?"Saving…":"Save customer changes"}</Button>\n      </div>\n    </DialogContent>\n  </Dialog>;\n}\n\n'''
    text=text.replace(marker,component+marker,1)

old='<div className="profile-head-actions"><MessageComposer customer={selected} estimate={customerEstimates[0]} initialTemplate="estimate" onLogged={(message)=>setMessages((current)=>[message,...current])}/><NewEstimate customer={selected} onSaved={handleEstimateSaved} /></div>'
new='<div className="profile-head-actions"><EditCustomer customer={selected} onUpdated={(updated)=>setCustomers((current)=>current.map((item)=>item.id===updated.id?updated:item))}/><MessageComposer customer={selected} estimate={customerEstimates[0]} initialTemplate="estimate" onLogged={(message)=>setMessages((current)=>[message,...current])}/><NewEstimate customer={selected} onSaved={handleEstimateSaved} /></div>'
if old not in text:
    if 'EditCustomer customer={selected}' not in text:
        raise SystemExit('FIRE_CUSTOMER_EDIT_FLOW=FAIL: customer profile action marker missing')
else:
    text=text.replace(old,new,1)

dashboard.write_text(text)
print('FIRE_CUSTOMER_EDIT_FLOW=PASS')
print('Customer profiles now support editing name, email, phone, service address, and lead source without rewriting existing estimate/invoice/payment history.')
